<?php $record=$page['record'];$editing=isset($record['id']);$locked=$record['status']!=='draft';$base='pagos.php?type='.$page['type']; ?>
<section><div class="contact-toolbar"><div><a class="overview-link" href="<?= $base ?>">← Pagos</a><h1><?= accountingEscape($record['name']) ?></h1></div><ol class="quotation-status" aria-label="Estado del pago"><?php foreach(paymentStatuses() as $key=>$label): ?><li <?= $record['status']===$key?'aria-current="step"':'' ?>><?= $label ?></li><?php endforeach; ?></ol></div>
<?php if($editing&&$record['status']!=='cancel'): ?><form class="quotation-state-actions" method="post" action="<?= $base ?>&amp;id=<?= (int)$record['id'] ?>" data-payment-transition><input type="hidden" name="csrf" value="<?= accountingEscape($page['csrf']) ?>"><input type="hidden" name="version" value="<?= (int)$record['version'] ?>"><?php if($record['status']==='draft'): ?><button class="contact-button contact-button-primary" name="action" value="post_payment">Registrar</button><?php elseif($record['status']==='pending'): ?><button class="contact-button contact-button-primary" name="action" value="settle_payment">Confirmar pago</button><?php endif; ?><button class="contact-button" name="action" value="cancel_payment">Cancelar</button><span class="section-subtitle" data-payment-dirty hidden>Guarda los cambios antes de continuar.</span></form><?php endif; ?>
<div class="contact-sheet"><form method="post" action="<?= $base ?><?= $editing?'&amp;id='.(int)$record['id']:'&amp;new=1' ?>" data-payment-form><input type="hidden" name="csrf" value="<?= accountingEscape($page['csrf']) ?>"><input type="hidden" name="action" value="save_payment"><input type="hidden" name="version" value="<?= (int)$record['version'] ?>"><?php if(!$editing): ?><input type="hidden" name="creation_key" value="<?= accountingEscape($page['creationKey']) ?>"><?php endif; ?>
<fieldset class="quotation-fields" <?= $locked?'disabled':'' ?>><div class="contact-form-grid"><label><?= $page['type']==='customer'?'Cliente':'Proveedor' ?> *<select name="contact_id" required><option value="">Selecciona un contacto</option><?php foreach($page['contacts'] as $contact): ?><option value="<?= (int)$contact['id'] ?>" <?= (int)($record['contact_id']??0)===(int)$contact['id']?'selected':'' ?>><?= accountingEscape($contact['name']) ?></option><?php endforeach; ?></select></label><label>Tipo de pago<select name="direction"><option value="inbound" <?= $record['direction']==='inbound'?'selected':'' ?>>Recibir dinero</option><option value="outbound" <?= $record['direction']==='outbound'?'selected':'' ?>>Enviar dinero</option></select></label>
<label>Importe *<input name="amount" inputmode="decimal" required value="<?= accountingEscape($record['amount']) ?>"></label><label>Moneda<select name="currency_code"><?php foreach(array_unique(array_merge(accountingCurrencyCodes($page['settings']),[$record['currency_code']])) as $code): ?><option value="<?= accountingEscape($code) ?>" <?= $record['currency_code']===$code?'selected':'' ?>><?= accountingEscape($code) ?></option><?php endforeach; ?></select></label><label>Fecha *<input type="date" name="payment_date" required value="<?= accountingEscape($record['payment_date']) ?>"></label><label>Referencia<input name="reference" maxlength="160" value="<?= accountingEscape($record['reference']) ?>"></label>
<label>Caja / banco<select name="account_id"><?php foreach($page['accounts'] as $account): ?><option value="<?= (int)$account['id'] ?>" <?= (int)($record['account_id']??0)===(int)$account['id']?'selected':'' ?>><?= accountingEscape($account['name']) ?><?= $account['currency_code']?' · '.accountingEscape($account['currency_code']):'' ?></option><?php endforeach; ?></select></label><label>Medio de pago<select name="method_id"><?php foreach($page['methods'] as $method): ?><option value="<?= (int)$method['id'] ?>" <?= (int)($record['method_id']??0)===(int)$method['id']?'selected':'' ?>><?= accountingEscape($method['name']) ?></option><?php endforeach; ?></select></label><label>Tasa de cambio<input name="exchange_rate" inputmode="decimal" value="<?= accountingEscape($record['exchange_rate']??'') ?>"><small>1 <?= accountingEscape($record['primary_code']) ?> = tasa en <?= accountingEscape($record['alternate_code']) ?>.</small></label></div></fieldset>
<?php if(!$locked): ?><div class="contact-form-actions"><button class="contact-button contact-button-primary">Guardar pago</button></div><?php endif; ?></form>
<?php if($editing): ?><dl class="quotation-totals"><div><dt>Aplicado</dt><dd><?= accountingEscape($record['allocated'].' '.$record['currency_code']) ?></dd></div><div><dt>Disponible para aplicar</dt><dd><?= accountingEscape($record['available'].' '.$record['currency_code']) ?></dd></div></dl>
<?php if($record['status']==='settled' && bccomp($record['available'],'0',2)>0): ?><p class="section-subtitle">El pago está confirmado. Su importe disponible se puede agregar a otras facturas del mismo contacto; no se asigna automáticamente.</p><?php endif; ?>
<div class="contact-notebook" data-notebook><nav class="notebook-tabs" data-notebook-tabs><a href="#payment-invoices" id="payment-tab-invoices">Facturas relacionadas</a></nav><section class="notebook-page" id="payment-invoices" data-notebook-page aria-labelledby="payment-tab-invoices">
<?php if($page['candidates']): ?><form method="post" action="<?= $base ?>&amp;id=<?= (int)$record['id'] ?>" data-payment-allocation><input type="hidden" name="csrf" value="<?= accountingEscape($page['csrf']) ?>"><input type="hidden" name="version" value="<?= (int)$record['version'] ?>"><input type="hidden" name="action" value="apply_payment"><div class="contact-form-grid"><label>Factura<select name="invoice_id" data-payment-invoice><?php foreach($page['candidates'] as $candidate): ?><option value="<?= (int)$candidate['id'] ?>" data-maximum="<?= accountingEscape($candidate['maximum']) ?>"><?= accountingEscape($candidate['name'].' · Pendiente '.$candidate['balance'].' '.$candidate['currency_code']) ?></option><?php endforeach; ?></select></label><label>Importe a aplicar (<?= accountingEscape($record['currency_code']) ?>)<input name="amount" inputmode="decimal" required data-payment-allocation-amount value="<?= accountingEscape($page['candidates'][0]['maximum']) ?>"></label></div><button class="contact-button contact-button-primary">Aplicar a factura</button></form><?php elseif(in_array($record['status'],['pending','settled'],true)&&bccomp($record['available'],'0',2)>0): ?><p class="section-subtitle">No hay facturas registradas con saldo que correspondan al contacto, tipo y monedas de este pago. El importe queda disponible para aplicarlo después.</p><?php endif; ?>
<div class="contact-table-wrap"><table class="contact-table"><thead><tr><th>Factura</th><th>Importe aplicado del pago</th><th>Importe en factura</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach($record['allocations'] as $allocation): ?><tr><td><a class="contact-name" href="index.php?type=<?= $page['type'] ?>&amp;id=<?= (int)$allocation['invoice_id'] ?>"><?= accountingEscape($allocation['invoice_name']) ?></a></td><td><?= accountingEscape($allocation['payment_amount'].' '.$record['currency_code']) ?></td><td><?= accountingEscape($allocation['amount'].' '.$allocation['currency_code']) ?></td><td><?= $allocation['status']==='cancel'?'Retirado':paymentStatuses()[$allocation['status']] ?></td><td><?php if($allocation['status']!=='cancel'&&$record['status']!=='cancel'): ?><form method="post" action="<?= $base ?>&amp;id=<?= (int)$record['id'] ?>"><input type="hidden" name="csrf" value="<?= accountingEscape($page['csrf']) ?>"><input type="hidden" name="version" value="<?= (int)$record['version'] ?>"><input type="hidden" name="invoice_id" value="<?= (int)$allocation['invoice_id'] ?>"><button class="contact-button contact-icon-button" name="action" value="unapply_payment" aria-label="Quitar de factura" title="Quitar de factura"><?php require dirname(__DIR__) . '/partials/unlink-icon.php'; ?></button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$record['allocations']): ?><tr><td colspan="5">El pago todavía no está aplicado a ninguna factura.</td></tr><?php endif; ?></tbody></table></div>
</section></div><?php endif; ?></div></section><script src="../../js/payments.js" defer></script>
